import katex from 'katex';
const math=s=>katex.renderToString(s,{displayMode:true,throwOnError:false});
const fmt=n=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:2}).format(n);
const num=n=>Number(n.toPrecision(6)).toString();
export function solveRevolutionAngle(target,full){if(!Number.isFinite(target)||target<=0||target>full*(1+1e-10))throw Error('El objetivo debe ser positivo y no superar el resultado de una vuelta completa.');return Math.min(360,360*target/full)}
export function initRevolutionLearning({setAngle,getContext}){
 const $=id=>document.getElementById(id);
 $('revResults').insertAdjacentHTML('afterend','<section class="rev-deep-dive"><div class="rev-learning-grid"><article><h2>Antes de girar: lee la figura</h2><div id="revProfileDiagram"></div><p>G<sub>L</sub>: centroide de la curva naranja. G<sub>A</sub>: centroide del área azul. Las distancias se miden perpendicularmente al eje; no confundas ambos puntos.</p></article><article><h2>Compara los dos teoremas</h2><div id="revComparison"></div><p>Superficie y volumen tienen unidades distintas: no se comparan sus valores como si fueran la misma magnitud.</p></article></div><section><h2>Del dibujo al cálculo</h2><div id="revWorked" class="rev-worked"></div></section><div class="rev-learning-grid"><section><h2>Problema inverso</h2><p>¿Qué ángulo hace falta para obtener una superficie o un volumen determinado con esta figura?</p><form id="revInverse"><label>Objetivo<select id="revTargetMode"><option value="volume">Volumen (cm³)</option><option value="surface">Superficie generada (cm²)</option></select></label><label>Valor<input id="revTarget" type="number" min="0" step="any" required inputmode="decimal"></label><button class="primary-btn">Calcular y mostrar el giro</button></form><div id="revInverseFeedback" role="status"></div></section><section><h2>Predice y comprueba</h2><label>Al girar la misma región 180° en lugar de 360°, sin solapamientos, el volumen es…<select id="revQuiz"><option value="">Elige</option><option value="half">La mitad</option><option value="quarter">La cuarta parte</option><option value="same">El mismo</option></select></label><p id="revQuizFeedback" role="status"></p><details><summary>¿Por qué no uso el punto central del círculo en un semicírculo?</summary><p>El centroide depende de la materia que distribuyes: un alambre semicircular y una lámina semicircular no equilibran en el mismo punto. La distancia es 2r/π para el arco y 4r/(3π) para el área.</p></details><details><summary>¿Y si el eje atraviesa la región?</summary><p>Se producen solapamientos: multiplicar área por recorrido del centroide puede contar volumen varias veces. Este laboratorio rechaza esas configuraciones; requiere otro análisis, no una aplicación directa de Pappus.</p></details></section></div></section>');
 $('revInverse').addEventListener('submit',event=>{event.preventDefault();try{const {profile:p}=getContext(),mode=$('revTargetMode').value,target=Number($('revTarget').value),full=mode==='volume'?p.volume:p.surface,degrees=solveRevolutionAngle(target,full);setAngle(degrees);$('revInverseFeedback').innerHTML=math(`\\theta=360^\\circ\\frac{${num(target)}}{${num(full)}}\\approx ${num(degrees)}^\\circ`)+`<p>Ángulo aplicado: ${fmt(degrees)}°. No se ha cambiado el tamaño de la figura.</p>`}catch(e){$('revInverseFeedback').textContent=e.message}});
 $('revQuiz').addEventListener('change',()=>{$('revQuizFeedback').textContent=$('revQuiz').value==='half'?'Correcto: Vθ = A·d·θ. Al reducir θ a la mitad, el volumen también se reduce a la mitad.':$('revQuiz').value?'No cambia el área ni la distancia del centroide; revisa el factor θ en la fórmula.':''});
 let lastSignature='';
 function update({profile:p,mode,angle,kind,r,h,offset}){
  if(p.axisX)kind='shifted-axis';
  $('revTargetMode').querySelector('[value="volume"]').disabled=p.hasRegion===false;
  if(p.hasRegion===false){
   $('revTargetMode').value='surface';
   const xs=p.curve.map(v=>v[0]),ys=p.curve.map(v=>v[1]),minY=Math.min(...ys),maxY=Math.max(...ys),s=Math.min(310/Math.max(...xs,1),220/Math.max(maxY-minY,1)),X=x=>55+x*s,Y=y=>265-(y-minY)*s;
   $('revProfileDiagram').innerHTML=`<svg viewBox="0 0 440 300" role="img" aria-label="Curva abierta y centroide"><path d="M55 10V285" stroke="#172033" stroke-width="3"/><text x="10" y="22">eje</text><polyline points="${p.curve.map(([x,y])=>`${X(x)},${Y(y)}`).join(' ')}" fill="none" stroke="#a54400" stroke-width="4"/><circle cx="${X(p.lx)}" cy="${Y(p.ly)}" r="6" fill="#9b3500"/><text x="${X(p.lx)+10}" y="${Y(p.ly)-12}">G</text></svg>`;
   $('revComparison').innerHTML=`<p><strong>Curva abierta: no define una región ni un volumen.</strong></p><p>L ≈ ${fmt(p.length)} cm · d ≈ ${fmt(p.lx)} cm</p><p>Superficie completa ≈ ${fmt(p.surface)} cm²</p><p>A ${fmt(angle)}°: ≈ ${fmt(p.surface*angle/360)} cm²</p>`;
   const signature=JSON.stringify([p.length,p.lx,kind]);if(lastSignature===signature)return;lastSignature=signature;
   $('revWorked').innerHTML=`<article><h3>1. Trazo generador</h3>${math(p.equation)}<p>Parámetro t entre 0 y 1.</p></article><article><h3>2. Centroide de la curva</h3>${math('L=\\int_C ds,\\quad d_L=\\frac{\\int_C x\\,ds}{L}')}${math('ds=\\sqrt{(dx/dt)^2+(dy/dt)^2}\\,dt')}<p>Aproximación mediante segmentos y sus puntos medios.</p></article><article><h3>3. Superficie</h3>${math('S=2\\pi Ld_L,\\quad S_\\theta=Ld_L\\theta')}${math(`S\\approx2\\pi(${num(p.length)})(${num(p.lx)})`)}<p>θ en radianes; sin solapamientos del barrido.</p></article>`;return;
  }
  const signature=JSON.stringify([p.area,p.length,p.cx,p.cy,p.lx,p.ly,mode,kind,r,h,offset]);
  $('revComparison').innerHTML=`<table><thead><tr><th>Dato</th><th>Curva → superficie</th><th>Región → volumen</th></tr></thead><tbody><tr><th>Generador</th><td>L = ${fmt(p.length)} cm</td><td>A = ${fmt(p.area)} cm²</td></tr><tr><th>Distancia</th><td>d<sub>L</sub> = ${fmt(p.lx)} cm</td><td>d<sub>A</sub> = ${fmt(p.cx)} cm</td></tr><tr><th>Vuelta completa</th><td>${fmt(p.surface)} cm²</td><td>${fmt(p.volume)} cm³</td></tr><tr><th>Giro actual ${fmt(angle)}°</th><td>${fmt(p.surface*angle/360)} cm²</td><td>${fmt(p.volume*angle/360)} cm³</td></tr></tbody></table>`;
  if(signature===lastSignature)return;lastSignature=signature;
  $('revInverseFeedback').textContent='';
  const xs=p.region.map(v=>v[0]),ys=p.region.map(v=>v[1]),maxX=Math.max(...xs,1),minY=Math.min(...ys)-.5,maxY=Math.max(...ys)+.5,width=440,height=300,s=Math.min(330/maxX,230/(maxY-minY)),X=x=>60+x*s,Y=y=>270-(y-minY)*s;
  const areaPoints=p.region.map(([x,y])=>`${X(x)},${Y(y)}`).join(' '),curvePoints=p.curve.map(([x,y])=>`${X(x)},${Y(y)}`).join(' ');
  $('revProfileDiagram').innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Figura generadora y centroides de la curva y del área"><path d="M60 15V285" stroke="#172033" stroke-width="3"/><text x="12" y="22">eje</text><polygon points="${areaPoints}" fill="#dbeafe" stroke="#517fae"/><polyline points="${curvePoints}" fill="none" stroke="#a54400" stroke-width="4"/>${[[p.lx,p.ly,'G_L','#9b3500'],[p.cx,p.cy,'G_A','#153fa0']].map(([x,y,name,color],i)=>`<path d="M60 ${Y(y)}H${X(x)}" stroke="${color}" stroke-dasharray="5 4"/><circle cx="${X(x)}" cy="${Y(y)}" r="6" fill="${color}"/><text x="${X(x)+10}" y="${Y(y)+(i?24:-14)}" fill="${color}">${name}</text>`).join('')}</svg>`;
  const areaMode=mode==='volume',base=areaMode?p.area:p.length,d=areaMode?p.cx:p.lx,letter=areaMode?'V':'S',symbol=areaMode?'A':'L',dSymbol=areaMode?'d_A':'d_L';
  let generator='',centroid='',result='';
  if(kind==='cylinder'){generator=areaMode?'A=rh':'L=h';centroid=areaMode?'d_A=b+\\frac r2':'d_L=b+r';result=areaMode?'V=2\\pi(rh)\\left(b+\\frac r2\\right)':'S=2\\pi h(b+r)'}
  else if(kind==='cone'){generator=areaMode?'A=\\frac{rh}{2}':'L=\\sqrt{r^2+h^2}';centroid=areaMode?'d_A=b+\\frac r3':'d_L=b+\\frac r2';result=areaMode?'V=2\\pi\\frac{rh}{2}\\left(b+\\frac r3\\right)':'S=2\\pi\\sqrt{r^2+h^2}\\left(b+\\frac r2\\right)'}
  else if(kind==='sphere'){generator=areaMode?'A=\\frac{\\pi r^2}{2}':'L=\\pi r';centroid=areaMode?'d_A=b+\\frac{4r}{3\\pi}':'d_L=b+\\frac{2r}{\\pi}';result=areaMode?'V=2\\pi\\frac{\\pi r^2}{2}\\left(b+\\frac{4r}{3\\pi}\\right)':'S=2\\pi(\\pi r)\\left(b+\\frac{2r}{\\pi}\\right)'}
  else if(kind==='torus'){generator=areaMode?'A=\\pi r^2':'L=2\\pi r';centroid=`${dSymbol}=b`;result=areaMode?'V=2\\pi^2br^2':'S=4\\pi^2br'}
  else if(kind==='ellipse'){generator=areaMode?'A=\\pi r\\frac h2':'L\\approx\\sum_i\\ell_i';centroid=`${dSymbol}=b`;result=areaMode?'V=2\\pi^2br\\frac h2':'S\\approx2\\pi bL'}
  else if(kind==='shifted-axis'){generator=areaMode?'A=\\iint_R dA':'L=\\int_C ds';centroid=areaMode?'d_A=|\\bar x_A-a|':'d_L=|\\bar x_L-a|';result=`${letter}=2\\pi ${symbol}${dSymbol}`}
  else {generator=areaMode?'A=\\frac12\\left|\\sum_i(x_i y_{i+1}-x_{i+1}y_i)\\right|':'L=\\sum_i\\ell_i';centroid=areaMode?'d_A=|\\bar x_A|':'d_L=\\frac{\\sum_i\\ell_i\\bar x_i}{L}';result=`${letter}=2\\pi ${symbol}${dSymbol}`}
  $('revWorked').innerHTML=`<article><h3>1. Medida del generador</h3>${math(generator)}${math(`${symbol}\\approx ${num(base)}\\;\\mathrm{cm}${areaMode?'^2':''}`)}</article><article><h3>2. Centroide correcto</h3>${math(centroid)}${math(`${dSymbol}\\approx ${num(d)}\\;\\mathrm{cm}`)}<p>b es la separación del generador respecto al eje; en el toro, la distancia del centro del círculo al eje.</p></article><article><h3>3. Recorrido y producto</h3>${math(`D=2\\pi ${dSymbol}`)}${math(result)}${math(`${letter}\\approx ${num(areaMode?p.volume:p.surface)}\\;\\mathrm{cm}^{${areaMode?3:2}}`)}<p>Para un giro parcial: multiplica el resultado de una vuelta por θ°/360°.</p></article>`;
  if(offset>0&&['cylinder','cone','sphere'].includes(kind))$('revWorked').insertAdjacentHTML('afterbegin','<p class="rev-offset-note"><strong>El eje está separado:</strong> ya no se genera el cuerpo macizo clásico de la ficha. El desplazamiento puede crear una cavidad. Observa el barrido y usa las distancias al eje actuales, no las fórmulas particulares del caso b = 0.</p>');
 }
 return {update};
}
